export const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
export const horizon={tomato:4,broccoli:4,carrot:12,potato:21,banana:4,apple:14,bread:3,egg:14,milk:5,pasta:90,chickpea:90,spinach:2,chicken:1,rice:90};
export const colours={tomato:'#e5533f',broccoli:'#43784b',carrot:'#e78532',potato:'#c8a66e',banana:'#eac34d',apple:'#b34145',bread:'#b17c43',egg:'#e9d4b4',milk:'#eee8dc',pasta:'#e5b552',chickpea:'#c1ad79',spinach:'#3b724e',chicken:'#d59c94',rice:'#f2ebd8'};
const seedStock=[['spinach',1,1],['broccoli',.5,3],['chicken',.4,1],['milk',1,5],['apple',.7,8],['bread',1,2],['carrot',.4,6]];
export const defaults=()=>({adults:1,kids:2,kidsHome:true,away:false,lunch:true,includePlanned:true,mainDay:'Sunday',topDay:'Wednesday',diet:'mixed',meals:[0,1,2,3,4,5,6],prices:{},inventory:seedStock.map(([id,qty,due])=>({id,qty,due,place:foods.find(f=>f.id===id).place,action:null})),checked:[],budget:130,retailer:'newworld',store:0,stores:[{name:'My usual shop',factor:100,fee:0,travel:3},{name:'Alternative shop',factor:100,fee:6,travel:4},{name:'Local top-up',factor:100,fee:0,travel:1}],events:[],day:0,sample:true});
export const num=(v,min,max,fallback)=>Number.isFinite(Number(v))?Math.max(min,Math.min(max,Number(v))):fallback;
export function sanitise(raw){const s=defaults();if(!raw||typeof raw!=='object')return s;for(const k of ['adults','kids'])s[k]=Math.round(num(raw[k],k==='adults'?1:0,8,s[k]));for(const k of ['kidsHome','away','lunch','sample','includePlanned'])if(typeof raw[k]==='boolean')s[k]=raw[k];if(['Saturday','Sunday','Monday'].includes(raw.mainDay))s.mainDay=raw.mainDay;if(['Wednesday','Thursday','None'].includes(raw.topDay))s.topDay=raw.topDay;if(raw.diet==='vegetarian')s.diet=raw.diet;s.budget=num(raw.budget,0,2000,130);s.day=Math.round(num(raw.day,0,6,0));s.store=Math.round(num(raw.store,0,2,0));if(['newworld','woolworths','paknsave'].includes(raw.retailer))s.retailer=raw.retailer;if(Array.isArray(raw.meals)&&raw.meals.length===7)s.meals=raw.meals.map((v,i)=>Number.isInteger(v)&&v>=0&&v<recipes.length?v:s.meals[i]);if(raw.prices&&typeof raw.prices==='object')foods.forEach(f=>{if(Object.hasOwn(raw.prices,f.id))s.prices[f.id]=num(raw.prices[f.id],0,200,f.price)});if(Array.isArray(raw.inventory)){s.inventory=[];for(const v of raw.inventory){if(!foods.some(f=>f.id===v?.id)||s.inventory.some(x=>x.id===v.id))continue;s.inventory.push({id:v.id,qty:num(v.qty,0,50,1),due:Math.round(num(v.due,-1,90,3)),place:['fridge','crisper','bench','pantry','freezer'].includes(v.place)?v.place:foods.find(f=>f.id===v.id).place,action:['used','wasted'].includes(v.action)?v.action:null});}}if(Array.isArray(raw.checked))s.checked=raw.checked.filter(v=>typeof v==='string'&&v.length<40);if(Array.isArray(raw.events))s.events=raw.events.slice(-50).filter(v=>v&&['used','wasted','frozen'].includes(v.action)&&foods.some(f=>f.id===v.id)).map(v=>({id:v.id,action:v.action,qty:num(v.qty,0,50,0),day:num(v.day,0,6,0)}));if(Array.isArray(raw.stores)&&raw.stores.length===3)s.stores=raw.stores.map((v,i)=>({name:s.stores[i].name,factor:num(v.factor,50,150,100),fee:num(v.fee,0,100,0),travel:num(v.travel,0,100,0)}));return s;}
export const serving=s=>s.adults+(s.kidsHome?s.kids*.6:0);
export function meal(s,d){const r=recipes[s.meals[d]]||recipes[0];return s.diet==='vegetarian'&&!r.veg?recipes[7]:r;}
export const unitPrice=(s,id)=>s.prices[id]??foods.find(f=>f.id===id).price;
export const roundQty=(id,q)=>Math.ceil((q-1e-8)*(foods.find(f=>f.id===id).unit==='kg'?10:1))/(foods.find(f=>f.id===id).unit==='kg'?10:1);
export function demands(s){return days.map((_,d)=>{if(s.away&&d>=5)return {};const p=serving(s);const out=Object.fromEntries(Object.entries(meal(s,d).ingredients).map(([id,q])=>[id,q*p]));for(const [id,q] of Object.entries({banana:p*.10,apple:p*.12,bread:p*.055,milk:p*.075}))out[id]=(out[id]||0)+q;if(s.lunch&&s.kidsHome&&d<5){out.apple+=s.kids*.09;out.bread+=s.kids*.04;}return out;});}
export function plan(s,{top=s.topDay,ignoreStock=false,store=s.store}={}){const demand=demands(s);const mainAt={Saturday:-2,Sunday:-1,Monday:0}[s.mainDay];const topAt=top==='None'?99:days.indexOf(top);const stocks=ignoreStock?[]:s.inventory.filter(x=>!x.action&&x.qty>0).map(x=>({...x,left:x.qty}));const requirements={main:{},top:{}};const avoided={};const stockUse={};const schedule=[];demand.forEach((day,d)=>{const consumed={};Object.entries(day).forEach(([id,q])=>{let need=q;const item=stocks.find(x=>x.id===id);if(item&&(item.place==='freezer'||item.due>=d)){const take=Math.min(item.left,need);item.left-=take;need-=take;avoided[id]=(avoided[id]||0)+take;consumed[id]=take;}if(need>1e-8){const food=foods.find(f=>f.id===id);const slot=d>=topAt&&!(food.place==='pantry'&&id!=='bread')?'top':'main';requirements[slot][id]=(requirements[slot][id]||0)+need;schedule.push({id,qty:need,day:d,slot,at:slot==='main'?mainAt:topAt});}});stockUse[d]=consumed;});const storeInfo=s.stores[store];const shops=['main',...(top==='None'?[]:['top'])].map(kind=>({kind,day:kind==='main'?s.mainDay:top,at:kind==='main'?mainAt:topAt,items:Object.entries(requirements[kind]).map(([id,q])=>({id,qty:roundQty(id,q),price:unitPrice(s,id)*storeInfo.factor/100})).map(f=>({...f,cost:f.qty*f.price}))}));const basket=shops.reduce((sum,x)=>sum+x.items.reduce((sum,i)=>sum+i.cost,0),0);const fee=shops.filter(x=>x.items.length).length*(storeInfo.fee+storeInfo.travel);const atRisk=schedule.filter(x=>x.day-x.at>horizon[x.id]).reduce((n,x)=>n+x.qty*unitPrice(s,x.id)*storeInfo.factor/100,0);return {shops,basket,fees:fee,total:basket+fee,avoided:Object.entries(avoided).reduce((n,[id,q])=>n+q*unitPrice(s,id),0),atRisk,stockUse,demand,schedule};}
export function stockStatus(stock,day){if(stock.action)return stock.action;if(stock.place==='freezer')return'frozen';if(stock.due<day)return'overdue';if(stock.due-day<=2)return'soon';return'fresh';}
export function sceneInventory(s){const p=plan(s);const out=s.inventory.map(x=>{let used=0;for(let d=0;d<s.day;d++)used+=p.stockUse[d]?.[x.id]||0;const qty=Math.max(0,x.qty-used);const f=foods.find(f=>f.id===x.id);return {...f,...x,qty,color:colours[x.id],status:stockStatus(x,s.day),projected:used>0,plannedQty:0};}).filter(x=>x.qty>.001&&!x.action);if(s.includePlanned){for(const shop of p.shops){if(shop.at>s.day)continue;for(const item of shop.items){const used=p.schedule.filter(x=>x.id===item.id&&x.slot===shop.kind&&x.day<s.day).reduce((n,x)=>n+x.qty,0);const qty=Math.max(0,item.qty-used);if(qty<.001)continue;const f=foods.find(f=>f.id===item.id);const due=shop.at+horizon[item.id];const existing=out.find(x=>x.id===item.id);if(existing){existing.qty+=qty;existing.plannedQty+=qty;}else out.push({...f,qty,due,action:null,color:colours[item.id],status:stockStatus({due,place:f.place},s.day),projected:true,plannedQty:qty});}}}return out;}
export function findFood(text){const aliases={tomato:['tomato'],broccoli:['broccoli'],carrot:['carrot'],potato:['potato'],banana:['banana'],apple:['apple'],bread:['bread','loaf'],egg:['egg'],milk:['milk'],pasta:['pasta','spaghetti','penne'],chickpea:['chickpea'],spinach:['spinach'],chicken:['chicken'],rice:['rice']};const t=text.toLowerCase();return foods.filter(f=>aliases[f.id].some(a=>new RegExp('\\b'+a+'(?:es|s)?\\b','i').test(t))).map(f=>f.id);}
